input.sparql:
SELECT ?zone ?label WHERE {
  ?zone a brick:Zone ; brick:hasSubProperty* ?nothing .
}
LIMIT 1

SELECT ?occ ?tsid WHERE {
  ?occ a brick:Occupancy_Sensor ; brick:hasInput "http://buildgraph.org/BG_medium_office_2004_0000#Zone_F2_Z02" .
  ?occ ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}
